import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene placement
  if (config.position) group.position.copy(config.position);
  if (config.rotation) {
    group.rotation.order = 'YXZ';
    if (config.rotation instanceof THREE.Vector3) {
      group.rotation.setFromVector3(config.rotation);
    }
  }
  if (config.scale) group.scale.copy(config.scale);

  // Design tokens
  const gridWidth = 5.5;
  const gridHeight = 3.5;
  const gutter = 0.25;
  const cellPadding = 0.5;
  const dominantW = 3.25;
  const dominantH = 3.5;
  const secondaryW = 2.0;
  const secondaryH = 1.625;
  const tickW = 0.4;
  const tickH = 0.05;

  // Colors
  const surfaceColor = 0x14141a;
  const gradStartColor = 0x101017;
  const gradEndColor = 0x1a1a22;
  const accentColor = 0xff2a38;

  // Helper: create a cell slab with gradient, material, and tick
  function createCell(width, height) {
    const cellGroup = new THREE.Group();

    // Main brushed-metal surface
    const mainGeo = new THREE.PlaneGeometry(width, height, 4, 4);
    const mainMat = new THREE.MeshStandardNodeMaterial({
      color: new THREE.Color(surfaceColor),
      roughness: 0.55,
      metalness: 0.45,
      clearcoat: 0.2,
      side: THREE.FrontSide,
    });
    const mainPlane = new THREE.Mesh(mainGeo, mainMat);
    cellGroup.add(mainPlane);

    // Engineered diagonal gradient overlay (135° sheen band)
    const gradGeo = new THREE.PlaneGeometry(width * 1.5, height * 1.5);
    const gradMat = new THREE.MeshBasicNodeMaterial({
      color: new THREE.Color(gradEndColor),
      transparent: true,
      opacity: 0.18,
      side: THREE.FrontSide,
    });
    const gradPlane = new THREE.Mesh(gradGeo, gradMat);
    gradPlane.position.z = 0.005;
    gradPlane.rotation.z = Math.PI * (135 / 180);
    cellGroup.add(gradPlane);

    // Accent tick bar (emissive, top-left inside padding)
    const tickGeo = new THREE.PlaneGeometry(tickW, tickH);
    const tickMat = new THREE.MeshBasicNodeMaterial({
      color: new THREE.Color(accentColor),
      emissive: new THREE.Color(accentColor),
      emissiveIntensity: 1.3,
      side: THREE.FrontSide,
    });
    const tickBar = new THREE.Mesh(tickGeo, tickMat);
    tickBar.position.set(
      -width / 2 + cellPadding + tickW / 2,
      height / 2 - cellPadding - tickH / 2,
      0.01
    );
    cellGroup.add(tickBar);

    return cellGroup;
  }

  // Calculate cell positions (grid centered at origin)
  const gridOffsetX = 0;
  const gridOffsetY = 0;

  // Dominant cell (left column, full height)
  const dominantCell = createCell(dominantW, dominantH);
  dominantCell.position.set(
    gridOffsetX - gridWidth / 2 + dominantW / 2,
    gridOffsetY,
    0
  );
  group.add(dominantCell);

  // Secondary cells (right column, stacked)
  const secondary1 = createCell(secondaryW, secondaryH);
  secondary1.position.set(
    gridOffsetX - gridWidth / 2 + dominantW + gutter + secondaryW / 2,
    gridOffsetY + (gridHeight - secondaryH) / 2 - gutter / 2,
    0
  );
  group.add(secondary1);

  const secondary2 = createCell(secondaryW, secondaryH);
  secondary2.position.set(
    gridOffsetX - gridWidth / 2 + dominantW + gutter + secondaryW / 2,
    gridOffsetY - (gridHeight - secondaryH) / 2 + gutter / 2,
    0
  );
  group.add(secondary2);

  const cells = [dominantCell, secondary1, secondary2];

  // Text content via font atlas
  // Header caption
  const headerMesh = ctx.fontAtlas.createTextMesh('ATELIER METRICS / Q2 2026', {
    font: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 700,
    letterSpacing: 0.12,
    lineHeight: 1.4,
  });
  headerMesh.position.set(
    gridOffsetX - gridWidth / 2 + cellPadding,
    gridOffsetY + gridHeight / 2 + 0.5,
    0.02
  );
  group.add(headerMesh);

  // Dominant cell: value + label
  const domValueMesh = ctx.fontAtlas.createTextMesh('0.002 mm', {
    font: 'Lora',
    fontSize: 124,
    fontWeight: 600,
    letterSpacing: -0.01,
    lineHeight: 1.0,
  });
  domValueMesh.position.set(
    dominantCell.position.x,
    dominantCell.position.y + 0.3,
    0.02
  );
  group.add(domValueMesh);

  const domLabelMesh = ctx.fontAtlas.createTextMesh('Case tolerance, CNC pass', {
    font: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    lineHeight: 1.4,
  });
  domLabelMesh.position.set(
    dominantCell.position.x,
    dominantCell.position.y - 0.5,
    0.02
  );
  group.add(domLabelMesh);

  // Secondary 1: value + label
  const sec1ValueMesh = ctx.fontAtlas.createTextMesh('38 h', {
    font: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.05,
  });
  sec1ValueMesh.position.set(
    secondary1.position.x,
    secondary1.position.y + 0.25,
    0.02
  );
  group.add(sec1ValueMesh);

  const sec1LabelMesh = ctx.fontAtlas.createTextMesh('Power reserve, NA-01', {
    font: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    lineHeight: 1.4,
  });
  sec1LabelMesh.position.set(
    secondary1.position.x,
    secondary1.position.y - 0.25,
    0.02
  );
  group.add(sec1LabelMesh);

  // Secondary 2: value + label
  const sec2ValueMesh = ctx.fontAtlas.createTextMesh('214', {
    font: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    lineHeight: 1.05,
  });
  sec2ValueMesh.position.set(
    secondary2.position.x,
    secondary2.position.y + 0.25,
    0.02
  );
  group.add(sec2ValueMesh);

  const sec2LabelMesh = ctx.fontAtlas.createTextMesh('Components per calibre', {
    font: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    lineHeight: 1.4,
  });
  sec2LabelMesh.position.set(
    secondary2.position.x,
    secondary2.position.y - 0.25,
    0.02
  );
  group.add(sec2LabelMesh);

  // Animation timelines
  const timelines = [];

  // Entrance: stagger-cards fade-up (dominant first, then secondaries)
  const entranceTimeline = gsap.timeline();
  cells.forEach((cell, idx) => {
    const animState = { opacity: 0, offsetY: 0.2 };

    entranceTimeline.to(
      animState,
      {
        opacity: 1,
        offsetY: 0,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        onUpdate: () => {
          cell.position.y += animState.offsetY - (animState.offsetY || 0);
          cell.traverse((child) => {
            if (child.material) {
              child.material.opacity = animState.opacity;
            }
          });
        },
      },
      idx * 0.08
    );
  });
  timelines.push(entranceTimeline);

  // Event handlers for hover interaction
  group.userData.handlers = {
    pointerover: (event) => {
      const targetMesh = event.object;
      let targetCell = null;

      // Find which cell this mesh belongs to
      for (const cell of cells) {
        if (cell.children.includes(targetMesh) || targetMesh === cell) {
          targetCell = cell;
          break;
        }
      }

      if (!targetCell) return;

      // Press-down animation
      const hoverTl = gsap.timeline();
      hoverTl.to(
        targetCell.scale,
        {
          x: 0.97,
          y: 0.97,
          duration: 0.12,
          ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
        }
      );

      timelines.push(hoverTl);
      targetCell.userData.hoverTimeline = hoverTl;
    },

    pointerout: (event) => {
      const targetMesh = event.object;
      let targetCell = null;

      // Find which cell this mesh belongs to
      for (const cell of cells) {
        if (cell.children.includes(targetMesh) || targetMesh === cell) {
          targetCell = cell;
          break;
        }
      }

      if (!targetCell) return;

      // Kill previous timeline
      if (targetCell.userData.hoverTimeline) {
        targetCell.userData.hoverTimeline.kill();
      }

      // Weighted-settle animation: overshoot to 1.04, settle to 1.0
      const settleTl = gsap.timeline();
      settleTl.to(
        targetCell.scale,
        {
          x: 1,
          y: 1,
          duration: 0.9,
          ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        }
      );

      timelines.push(settleTl);
    },
  };

  // Cleanup resources
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
